def swimInWaterBS(grid: list[list[int]]) -> int:
    n = len(grid)
    from collections import deque
    def can_reach(t):
        if grid[0][0] > t: return False
        q = deque([(0, 0)])
        visited = {(0, 0)}
        while q:
            r, c = q.popleft()
            if r == n - 1 and c == n - 1: return True
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in visited and grid[nr][nc] <= t:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return False
    lo, hi = 0, n * n - 1
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        if can_reach(mid):
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

